solution:
use xiom.io;

use xiom.string;
fn validate_email(email: Str) -> Result[Str, Str] {
  if string.str_len(email) < 6 {
    return Err("Email too short — must be at least 6 characters");
  }
  if !string.str_contains(email, "@") {
    return Err("Email must contain '@'");
  }
  if !string.str_contains(email, ".") {
    return Err("Email must contain a dot (.)");
  }
  return Ok("Email is valid");
}

fn main() -> Int {
  match validate_email("user@gmail.com") {
    Ok(_) => { return 200; }
    Err(_) => { return 400; }
  }
}
